/**
 * @brief  2-class sleep staging inference
 * @param  features  输入特征向量 (SLEEP_N_FEATURES floats)
 * @param  output    输出概率 [P(wake), P(sleep)] (2 floats)
 */
static inline void sleep_predict(const float *feat, float *output) {
    int tree_offset = 0;
    int leaf_offset = 0;
    float raw_score = 0.0f;  // [FIX] LightGBM 二分类 leaf value 是标量, 用单值累加替代 output[2]

    for (int t = 0; t < SLEEP_N_TREES; t++) {
        int tree_size = sleep_tree_sizes[t];

        // Traverse tree
        int idx = tree_offset;
        int end = tree_offset + tree_size;
        int leaf_cnt = 0;  /* [2026-07-04 FIX]: 跟踪当前树内已跳过的叶子数 */
        while (idx < end) {
            if (sleep_features[idx] == 0xFFFF) {  /* [FIX] uint16 sentinel: 255与split_feature=255冲突 */
                // Leaf: accumulate raw score (1 value per leaf for binary LGBM)
                /* [2026-07-04 FIX]: 原为 sleep_leaf_values[leaf_offset]
                 *   ——每树固定取第 1 个叶子, 其他 (tree_size+1)/2-1 个叶子从未被访问
                 *   导致 raw_score 恒等 → P(sleep) 恒等 0.2274
                 *   leaf_cnt = BFS 遍历过程中经过的叶子计数, leaf_offset+leaf_cnt = 正确的叶子 */
                raw_score += sleep_leaf_values[leaf_offset + leaf_cnt];
                break;
            }
            if (feat[sleep_features[idx]] <= sleep_thresholds[idx]) {
                idx++;  // left child (next index)
            } else {
                // Right child: skip all left subtree nodes
                // Find right child by skipping left subtree
                int skip = 1;
                int temp = idx + 1;
                while (skip > 0 && temp < end) {
                    if (sleep_features[temp] != 0xFFFF) skip++; // internal node: 2 children
                    else { skip--; leaf_cnt++; }  /* [2026-07-04 FIX]: 跳过的叶子 = leaf_cnt 增量 */
                    temp++;
                }
                idx = temp;
            }
        }
        
        tree_offset += tree_size;
        // [FIX] 二分类 LightGBM 每叶只有 1 个标量值, 不再 ×SLEEP_N_CLASSES
        leaf_offset += (tree_size + 1) / 2;  // leaves = (nodes+1)/2
    }

    // [FIX] sigmoid 替代 softmax: 二分类时数学等价, 且 leaf value 是标量
    float p_sleep = 1.0f / (1.0f + expf(-raw_score));
    output[0] = 1.0f - p_sleep;  // P(wake)
    output[1] = p_sleep;          // P(sleep)
}

/**
 * @brief  便捷接口：返回预测的睡眠类别
 * @return 0=Wake, 1=Sleep
 */
static inline int sleep_predict_class(const float *features) {
    float probs[2] = {0.0f, 0.0f};
    sleep_predict(features, probs);
    return probs[1] > probs[0] ? 1 : 0;
}


